// ============================================
// VALIDATION INPUT - Mathpix OCR
// RFC-014 Extraction with context.* fallback
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (extract for tracing, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- REQUIRED parameters ---
const imageUrl = body.image_url || ctx.image_url || null;
const imageBase64 = body.image_base64 || ctx.image_base64 || null;
const mathpixAppId = body.mathpix_app_id || ctx.mathpix_app_id || null;
const mathpixAppKey = body.mathpix_app_key || ctx.mathpix_app_key || null;

// Validate required fields
if (!imageUrl && !imageBase64) {
  errors.push('image_url ou image_base64 requis');
}
if (!mathpixAppId) {
  errors.push('mathpix_app_id requis');
}
if (!mathpixAppKey) {
  errors.push('mathpix_app_key requis');
}

// --- OPTIONAL parameters with defaults ---
const formats = body.formats || ctx.formats || ['latex_styled', 'text', 'data'];
const includeAsciimath = body.include_asciimath !== undefined ? body.include_asciimath : (ctx.include_asciimath !== undefined ? ctx.include_asciimath : true);
const includeLatex = body.include_latex !== undefined ? body.include_latex : (ctx.include_latex !== undefined ? ctx.include_latex : true);
const includeMathml = body.include_mathml || ctx.include_mathml || false;
const includeSvg = body.include_svg || ctx.include_svg || false;
const improveMathpix = body.improve_mathpix || ctx.improve_mathpix || false;

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// Determine image source
let imageSource = 'url';
let imageSrc = imageUrl;
if (imageBase64 && !imageUrl) {
  imageSource = 'base64';
  imageSrc = 'data:image/jpeg;base64,' + imageBase64;
}

return {
  valid: true,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  image_url: imageUrl,
  image_base64: imageBase64,
  image_source: imageSource,
  image_src: imageSrc,
  mathpix_app_id: mathpixAppId,
  mathpix_app_key: mathpixAppKey,
  formats: formats,
  include_asciimath: includeAsciimath,
  include_latex: includeLatex,
  include_mathml: includeMathml,
  include_svg: includeSvg,
  improve_mathpix: improveMathpix,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'mathpix',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

