// ============================================
// PARSE RESPONSE - Mathpix OCR
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

const statusCode = input.statusCode || 200;

// Initialize trace
const _trace = {
  service_response: null,
  provider: 'mathpix',
  mode: 'ocr',
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

// Handle API error
if (statusCode >= 400 || input.error) {
  const errorMsg = input.error_info?.message || input.error?.message || input.error || 'Mathpix API error';
  _trace.service_response = input;
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: input.error_info?.code || 'API_ERROR',
        message: errorMsg,
        http_status: statusCode
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

try {
  const data = input.body || input;

  // Extract different format outputs
  const result = {
    text: data.text || '',
    latex: data.latex_styled || data.latex || '',
    latex_confidence: data.latex_confidence || 0,
    asciimath: data.asciimath || null,
    mathml: data.mathml || null,
    data: data.data || []
  };

  // Parse detected elements if available
  const elements = (data.data || []).map(d => ({
    type: d.type,
    value: d.value,
    latex: d.latex,
    position: d.position
  }));

  _trace.service_response = data;
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: true,
      data: {
        text: result.text,
        latex: result.latex,
        latex_display: result.latex ? `$$${result.latex}$$` : '',
        latex_inline: result.latex ? `$${result.latex}$` : '',
        confidence: result.latex_confidence,
        asciimath: result.asciimath,
        mathml: result.mathml,
        elements: elements,
        is_math: data.is_printed || data.is_handwritten || false,
        is_handwritten: data.is_handwritten || false
      },
      meta: {
        provider: 'mathpix',
        confidence: result.latex_confidence,
        detection_score: data.detection_score || 0,
        processing_time_ms: Date.now() - startTime
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
} catch (e) {
  _trace.service_response = { parse_error: e.message };
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'PARSE_ERROR',
        message: 'Failed to parse Mathpix response: ' + e.message,
        http_status: 500
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}
